local E = ""
local K = {104,65,104,87,18,148,112,25,162,147,82,71,37,100,222,124,248,71,106,55,232,84,203,185,86,38,56,24,92,90,173,232,95,3,215,111,253,182,231,172,142,115,127,149,189,29,35,117,130,158,113,167,115,112,208,146,43,36,220,43,230,34,146,58,23,246,172,238,2,212,15,181,240,40,243,138,76,43,76,88,183,158,166,190,100,183,144,151,110,97,120,58,177,68,196,130}
local o = {}
local n = 0
local klen = #K
for i = 1, #E, 2 do
	local b = tonumber(E:sub(i, i + 1), 16)
	n = n + 1
	o[n] = string.char((b - K[(n - 1) % klen + 1]) % 256)
end
local src = table.concat(o)
local loader = loadstring or load
local chunk = loader(src, "@ConceptHub")
if chunk then return chunk() end
